CREATE TABLE IF NOT EXISTS `password_reset_token` (`id` BIGINT NOT NULL AUTO_INCREMENT, `token_digest` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `token_fingerprint` CHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `user_user` BIGINT NOT NULL, `requested_by_user` BIGINT NOT NULL, `expires_at` BIGINT NOT NULL, `consumed_at` BIGINT NULL, `invalidated_at` BIGINT NULL, `created_at` BIGINT NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_password_reset_token_digest` (`token_digest`), KEY `idx_password_reset_token_user_active` (`user_user`, `consumed_at`, `invalidated_at`, `expires_at`, `id`), KEY `idx_password_reset_token_expiry` (`expires_at`, `id`), KEY `idx_password_reset_token_requester` (`requested_by_user`, `created_at`, `id`), CONSTRAINT `fk_password_reset_token_user` FOREIGN KEY (`user_user`) REFERENCES `users` (`id`) ON DELETE RESTRICT, CONSTRAINT `fk_password_reset_token_requested_by` FOREIGN KEY (`requested_by_user`) REFERENCES `users` (`id`) ON DELETE RESTRICT, CONSTRAINT `chk_password_reset_token_expiry` CHECK (`expires_at` > `created_at`), CONSTRAINT `chk_password_reset_token_consumed` CHECK (`consumed_at` IS NULL OR `consumed_at` >= `created_at`), CONSTRAINT `chk_password_reset_token_invalidated` CHECK (`invalidated_at` IS NULL OR `invalidated_at` >= `created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
